import React, { useState, useEffect, useCallback } from 'react';
import NotificationStrip from 'webapp/components/NotificationStrip';
import { useDashboardConfig } from './useDashboardConfig';
import userPrefs from 'webapp/lib/userPrefs';

const DISMISS_KEY_PREFIX = 'dashboardBannerDismissed:';

function useAnnouncementDismissal(campaignId?: string): [boolean, () => void] {
  const key = campaignId ? `${DISMISS_KEY_PREFIX}${campaignId}` : null;

  const [dismissed, setDismissed] = useState<boolean>(() => {
    if (!key) return false;
    try {
      return !!userPrefs.get(key);
    } catch {
      return false;
    }
  });

  useEffect(() => {
    if (!key) {
      setDismissed(false);
      return;
    }
    try {
      setDismissed(!!userPrefs.get(key));
    } catch {
      setDismissed(false);
    }
  }, [key]);

  const dismiss = useCallback(() => {
    if (!key) return;
    try {
      userPrefs.set(key, true);
    } catch {
      /* swallow storage errors to avoid noisy console output */
    }
    setDismissed(true);
  }, [key]);

  return [dismissed, dismiss];
}

const AnnouncementBanner: React.FC = () => {
  const cfg = useDashboardConfig() || {};
  const activeBanner = cfg.activeBanner ?? null;

  if (!activeBanner) return null;

  const campaignId = (activeBanner as any).campaignId;
  const [dismissed, dismiss] = useAnnouncementDismissal(campaignId);

  if (dismissed) return null;

  // Keep props generic to match existing NotificationStrip usage:
  return (
    <NotificationStrip
      message={(activeBanner as any).message || (activeBanner as any).text || ''}
      ctaLabel={(activeBanner as any).ctaLabel}
      ctaHref={(activeBanner as any).ctaUrl || (activeBanner as any).cta}
      onClose={dismiss}
    />
  );
};

export default AnnouncementBanner;
```

