import React from 'react';
import { render, fireEvent } from '@testing-library/react';
import AnnouncementBanner from '../AnnouncementBanner';

jest.mock('webapp/lib/userPrefs', () => ({
  get: jest.fn(),
  set: jest.fn(),
}));
import userPrefs from 'webapp/lib/userPrefs';

jest.mock('../useDashboardConfig', () => ({
  useDashboardConfig: jest.fn(),
}));
import { useDashboardConfig } from '../useDashboardConfig';

describe('AnnouncementBanner dismissal behavior', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('first visit: banner visible; clicking close hides it and persists preference', () => {
    (userPrefs.get as jest.Mock).mockReturnValue(undefined);
    (useDashboardConfig as jest.Mock).mockReturnValue({
      activeBanner: { campaignId: 'camp-1', message: 'Big sale!' },
    });

    const { getByText, getByRole, queryByText } = render(<AnnouncementBanner />);
    expect(getByText('Big sale!')).toBeInTheDocument();

    const closeBtn = getByRole('button', { name: /close|dismiss|got it|×|x/i });
    fireEvent.click(closeBtn);

    expect(userPrefs.set).toHaveBeenCalledWith('dashboardBannerDismissed:camp-1', true);
    expect(queryByText('Big sale!')).toBeNull();
  });

  test('stay hidden on refresh when preference set for same campaignId', () => {
    (userPrefs.get as jest.Mock).mockReturnValue(true);
    (useDashboardConfig as jest.Mock).mockReturnValue({
      activeBanner: { campaignId: 'camp-1', message: 'Old sale' },
    });

    const { queryByText } = render(<AnnouncementBanner />);
    expect(queryByText('Old sale')).toBeNull();
    expect(userPrefs.get).toHaveBeenCalledWith('dashboardBannerDismissed:camp-1');
  });

  test('new campaignId shows again even if previous was dismissed', () => {
    (userPrefs.get as jest.Mock).mockImplementation((key: string) =>
      key === 'dashboardBannerDismissed:camp-1' ? true : undefined
    );

    (useDashboardConfig as jest.Mock).mockReturnValue({
      activeBanner: { campaignId: 'camp-2', message: 'New campaign' },
    });

    const { getByText } = render(<AnnouncementBanner />);
    expect(getByText('New campaign')).toBeInTheDocument();
  });

  test('no noisy console errors when no banner returned', () => {
    const spy = jest.spyOn(console, 'error').mockImplementation(() => {});
    (useDashboardConfig as jest.Mock).mockReturnValue({ activeBanner: null });

    const { container } = render(<AnnouncementBanner />);
    expect(container.firstChild).toBeNull();
    expect(spy).not.toHaveBeenCalled();
    spy.mockRestore();
  });
});
```

